import json
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'outputs/movement/joint';OLD=ROOT/'outputs/movement/comparison'
def fmt(x):return '—' if x is None else f'{x:.3f}'
def main():
 r=json.loads((OUT/'metrics.json').read_text());names={'original':'原移动模型','enriched_move':'武器/交火信息 + 移动模型','joint':'移动 + 动作联合模型'};types={'fire':'枪械开火','smoke':'烟雾弹出手','flash':'闪光弹出手','he':'手雷出手','incendiary':'燃烧弹出手','decoy':'诱饵弹出手'};a=r['ADE'];audit=r['audit']
 lines=['# 移动、开枪与道具联合模型：开发验证报告','', '日期：2026-10-13。状态：本地实验完成；沿用已查看的测试比赛，属于探索性开发验证。','', '## 主要结果','',f'原模型 / 新信息移动模型 / 联合模型的平均位移误差分别为 **{a["original"]:.2f} / {a["enriched_move"]:.2f} / {a["joint"]:.2f}** 游戏单位，越低越好。',f'联合模型相对原模型误差改善 **{(a["original"]-a["joint"])/a["original"]*100:+.2f}%**；新增信息但不做动作监督时改善 **{(a["original"]-a["enriched_move"])/a["original"]*100:+.2f}%**。负数表示变差。','',f'按六场系列赛等权比较，联合模型的平均误差改善为 {r["paired_improvement"]["mean"]:.2f}，配对比赛 bootstrap 95% 区间为 {r["paired_improvement"]["ci95"]}。小样本且测试集已查看，不用于确认性结论。','', '当前结果没有显示位移改善。烟雾弹、闪光弹出手预测有初步信号，但测试正例分别仅 15 和 23 个。开枪预测 AP 为 0.069，低于最近开枪延续基准的 0.161，Brier 也略差于训练先验，当前交战预测不合格。诱饵弹在训练和测试均无正例，不能称为已学会该动作。', '', '## 这次实际实现的内容','', '- 77 份 demo、7 张地图；沿用上轮相同的 4,928 个窗口及 19/5/6 场训练/验证/测试划分。自动逐样本核对原始历史、上下文、目标轨迹与旧数据一致。','- 新增 26 维每帧信息：武器类别及有效标记、弹夹子弹与有效标记、换弹与有效标记、五类道具库存与有效标记、最近两秒自身六类动作计数、受到的伤害、采样帧间武器变化。','- 枪械开火与挥刀分开；道具采用 grenade_thrown 出手事件，而不是爆炸或落地时间。','- 只使用每一历史时点之前的自身事件；玩家受伤不附带攻击者身份或隐藏坐标。全局敌方开枪事件没有进入输入。','- 输出：未来 0.5、1、2 秒相对位置，以及六类动作各自首次发生于 (0,0.5]、(0.5,1]、(1,2] 或两秒内不发生的概率。不同类别可同时发生；不预测精确投掷落点。',f'- {audit["weapon_rows"]:,} 个选中历史状态中，弹药有效 {audit["ammo_known"]:,}，换弹有效 {audit["reload_known"]:,}。缺失值保留独立标记，不假装为零子弹或未换弹。',f'- 77 份录像读取了 {audit["fire_events"]:,} 条枪械开火事件、{audit["grenade_events"]:,} 条道具出手事件。该数量含全局/非训练窗口事件，不能等同于训练标签数量。','', '## 实验设置','', '- 三组各训练三个固定种子 7/17/29，100 epoch，AdamW lr=0.001、weight_decay=0.01、batch=256。','- 三组均按验证集位移 ADE 选择 checkpoint；动作指标是次要结果，没有用测试动作效果挑选配置。','- 联合 loss = 平均位移欧氏误差（归一化尺度）+ 0.15 × 六类首次动作时间分类交叉熵。','- 动作采用各类别四分类，可同时预测不同类型发生；不是强制互斥的“只开枪或只扔雷”。','- 网络预测行为概率，不把“遇敌开枪必须停下”写成硬规则。','', '## 移动结果','', '| 模型 | 全部测试 ADE | 明显移动片段 ADE |','|---|---:|---:|']
 for k,n in names.items():lines.append(f'| {n} | {a[k]:.2f} | {r["moving_ADE"][k]:.2f} |')
 lines+=['', '### 各地图 ADE','', '| 地图 | 原模型 | 新信息移动 | 联合模型 |','|---|---:|---:|---:|']
 for m,v in r['by_map'].items():lines.append(f'| {m} | {v["original"]:.2f} | {v["enriched_move"]:.2f} | {v["joint"]:.2f} |')
 lines+=['', '## 动作预测结果','', 'AP（平均精确率）越高越好；常数概率 AP 等于事件比例。Brier 越低越好，比较概率是否准确。稀有道具的测试正例很少，不能仅靠一个 AP 宣称学会投掷决策。','', '| 动作 | 训练正例 | 验证正例 | 测试正例 | 模型 AP | 先验 AP | 近期动作基准 AP | 模型 Brier | 先验 Brier |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
 for k,v in r['actions'].items():lines.append(f'| {types[k]} | {v["train_positive"]} | {v["validation_positive"]} | {v["model"]["positive"]} | {fmt(v["model"]["AP"])} | {fmt(v["training_prior"]["AP"])} | {fmt(v["repeat_recent_action"]["AP"])} | {fmt(v["model"]["Brier"])} | {fmt(v["training_prior"]["Brier"])} |')
 lines+=['', '先验概率只由训练集发生率估计。详细 JSON 还包含“最近两秒做过该动作就预测继续做”的简单基准。','', '| 动作 | 已发生条件下首次时间段准确率 | 最常见时间段基准 |','|---|---:|---:|']
 for k,v in r['actions'].items():lines.append(f'| {types[k]} | {fmt(v["first_bin_accuracy_given_event"])} | {fmt(v["prior_first_bin_accuracy_given_event"])} |')
 lines+=['', '该时间准确率仅在真实有事件时计算，并从三个事件时间段中选择，不能理解成端到端检测准确率。','', '## 局限与下一步','', '1. 暂未模拟枪声可听性。听声信息必须结合距离、障碍、音源和不确定性；不能把全局开火自动当成玩家听到。','2. 暂未接入可见敌人的历史、地图遮挡、已生效烟火闪、掩体和穿墙伤害。这是动作因素的第一阶段，不是完整局势决策模型。','3. 只保留完整历史/未来窗口均存活的样本，不能评价暴露导致死亡的风险；后续需要加入死亡及截断轨迹样本。','4. 0.5 秒历史采样不能精确刻画急停与开枪相差几十毫秒的控制操作；要评价急停时机需更细采样和实际武器射击精度状态。','5. 普通回归路径可能穿墙，动作和路径仍可能不协调；目前没有物理约束或可执行操作序列检查。','6. 职业实际行为不是最优解；尚不用于给普通玩家判错或替换网站建议。没有悄悄上线本模型。','7. 增加道具正例时，可仅对训练集做事件邻域采样，验证/测试仍保留自然发生率。用新的整场比赛再做确认验证。','', '## 运行与检查','',f'- 九次训练及评估耗时 {r["seconds"]:.1f} 秒，PyTorch 峰值分配显存 {r["peak_mb"]:.1f} MiB；不含 demo 解析时间。','- 无外部 API、无 Qwen 调用。','- 9 项 Python 检查通过；事件边界检查通过（挥刀排除、未来不入历史、目标时间段无重叠、缺失值标记）。','- 九份 checkpoint、逐样本动作概率、位移预测、协议及详细指标保存在本报告目录。predict_joint.py 已完成单样本离线推理检查；示例保存为 prediction-example.json，无训练正例的诱饵弹明确输出 unsupported。','', '## 复现','', '在 Cs2-agent 根目录执行：','', '```powershell','./.venv/Scripts/python.exe experiments/movement/extract_joint.py','./.venv/Scripts/python.exe experiments/movement/train_joint.py','./.venv/Scripts/python.exe experiments/movement/report_joint.py','```','']
 (OUT/'移动开枪道具-联合模型验证报告.md').write_text('\n'.join(lines),encoding='utf-8');print('\n'.join(lines[:12]))
if __name__=='__main__':main()
